import { articles, topics, filterArticles, pageItems, escapeHtml as e, highlight } from './data.mjs'
// 独立设计样稿。业务接口、数据库、登录与浏览器持久存储均不参与。
const $ = (s,root=document)=>root.querySelector(s)
const app=$('#app'), searchDialog=$('#search-dialog'), infoDialog=$('#info-dialog')
const paths={arrow:'M4 10h12m-4-4 4 4-4 4',search:'m14 14 4 4M9 15a6 6 0 1 0 0-12 6 6 0 0 0 0 12',menu:'M3 5h14M3 10h14M3 15h14'}
const icon=(name='arrow')=>`<svg class="icon" viewBox="0 0 20 20" aria-hidden="true"><path d="${paths[name]}"/></svg>`
const href=(path,params={})=>'#'+path+(new URLSearchParams(Object.entries(params).filter(([,v])=>v!==''&&v!=null)).size?'?'+new URLSearchParams(Object.entries(params).filter(([,v])=>v!==''&&v!=null)):'')
const link=(path,label,params={},cls='')=>`<a class="${cls}" href="${e(href(path,params))}">${label}</a>`
const external=url=>{try{const u=new URL(url);return u.protocol==='https:'&&u.hostname==='github.com'?e(u.href):'#'}catch{return '#'}}
const repoLink=(repo,label='GitHub ↗')=>`<a class="text-link" href="${external(repo.url)}" target="_blank" rel="noopener noreferrer">${e(label)}</a>`
const route=()=>{const url=new URL((location.hash.slice(1)||'/'),'http://sample.local');return {path:url.pathname,params:Object.fromEntries(url.searchParams)}}
let snapshot=null, projectError=false, focused=false, fontSize=16, observer=null, noticeTimer
const positions=new Map()
let previousKey=location.hash||'#/'
let returnFocus=null

// 原创SVG用内容结构作封面，保留现有字母f与薄荷绿，不依赖图片服务。
function art(kind='flow') {
  const colors={flow:['#1d3129','#c2d7aa'],database:['#20302e','#a4c7bd'],state:['#2b3024','#d0cea3'],paper:['#303028','#d7cba8'],layout:['#252d34','#b4c7d2'],landscape:['#2a3028','#bdcda8']}
  const [bg,ink]=colors[kind]??['#242d25','#bbccad']
  const grid='<path d="M30 50H450M30 100H450M30 150H450M30 200H450M30 250H450M80 25V270M160 25V270M240 25V270M320 25V270M400 25V270" opacity=".07"/>'
  let drawing
  if(kind==='database') drawing='<ellipse cx="215" cy="80" rx="70" ry="25"/><path d="M145 80v125c0 34 140 34 140 0V80m-140 42c0 34 140 34 140 0m-140 42c0 34 140 34 140 0"/><circle cx="314" cy="186" r="35" fill="'+bg+'"/><path d="m297 186 12 12 22-26"/><path d="M108 115H65m43 30H80m28 30H55" opacity=".5"/>'
  else if(kind==='state') drawing='<circle cx="85" cy="145" r="25"/><rect x="190" y="115" width="100" height="60" rx="8"/><circle cx="395" cy="145" r="25"/><path d="M110 145h80m100 0h80m-189-7 9 7-9 7m180-14 9 7-9 7M240 175v45H85v-50"/><path d="m78 180 7-10 7 10"/><circle cx="395" cy="145" r="17"/><text x="240" y="150" text-anchor="middle" stroke="none" fill="'+ink+'" font-size="12">VALIDATE</text>'
  else if(kind==='paper') drawing='<path d="m147 64 139-15 22 190-140 16Z" opacity=".3"/><rect x="161" y="55" width="140" height="185" rx="3" fill="'+bg+'"/><path d="M185 91h88m-88 19h67m-67 40h88m-88 19h77m-77 19h56"/><path d="m235 224 63-64 10 10-65 62-12 2Z" fill="'+bg+'"/>'
  else if(kind==='layout') drawing='<rect x="65" y="70" width="240" height="157" rx="6"/><path d="M65 95h240M90 118h95v83H90zM202 120h75m-75 20h75m-75 20h54m-54 20h65"/><rect x="326" y="110" width="79" height="130" rx="8" fill="'+bg+'"/><path d="M337 130h57v47h-57zm0 61h57m-57 15h37"/>'
  else if(kind==='landscape') drawing='<circle cx="325" cy="90" r="28"/><path d="M30 222 147 110l78 88 54-45 171 87M30 251h420M120 238v-83m0 25-17-15m17 34 22-19"/><path d="M176 263c40-37 90-20 141-45" opacity=".5"/>'
  else if(!kind) drawing='<path d="M165 92h150v116H165zM189 120h98m-98 23h73m-73 23h85"/><text x="240" y="247" text-anchor="middle" stroke="none" fill="'+ink+'" font-size="11">FIELD NOTE / NO COVER</text>'
  else drawing='<rect x="50" y="113" width="106" height="76" rx="6" fill="'+bg+'"/><path d="M50 132h106m-84 18 8 7-8 7m17 0h21M156 152h62m-9-7 9 7-9 7"/><rect x="218" y="105" width="89" height="94" rx="6" fill="'+bg+'"/><path d="M235 125h55m-55 15h36m-36 15h48m-48 15h27M307 152h55m-9-7 9 7-9 7"/><ellipse cx="396" cy="125" rx="34" ry="13"/><path d="M362 125v54c0 18 68 18 68 0v-54m-68 27c0 18 68 18 68 0"/><text x="103" y="221" text-anchor="middle" stroke="none" fill="'+ink+'" font-size="10">BROWSER</text><text x="263" y="230" text-anchor="middle" stroke="none" fill="'+ink+'" font-size="10">API</text><text x="396" y="221" text-anchor="middle" stroke="none" fill="'+ink+'" font-size="10">DATA</text>'
  return `<svg viewBox="0 0 480 290" aria-hidden="true"><rect width="480" height="290" fill="${bg}"/><g fill="none" stroke="${ink}" stroke-width="1.4" font-family="Consolas,monospace">${grid}${drawing}</g><text x="30" y="32" fill="${ink}" opacity=".7" font-family="Consolas,monospace" font-size="9" letter-spacing="2">FIREFLY / ${e((kind||'NOTE').toUpperCase())}</text><circle cx="447" cy="30" r="3" fill="${ink}"/></svg>`
}
function articleUrl(a,from='/articles') { return href('/article/'+a.id,{from}) }
const meta=a=>`<div class="meta"><span>${e(a.kind)}</span><span>·</span><span>${e(a.tag)}</span><span>${a.minutes} 分钟</span></div>`
function pathCard(){return `<aside class="path-card"><span class="eyebrow">READING PATH / 演示专题</span><h3>从请求到交付</h3><p>从一个小功能出发，读懂完整流程。</p>${topics[0].ids.map((id,i)=>{const a=articles.find(x=>x.id===id);return `<a class="path-item" href="${e(articleUrl(a,'/articles?topic=web'))}"><span class="mono">0${i+1}</span>${e(['理解一条请求','照顾不同屏幕','验证备份恢复'][i])}<span>↗</span></a>`}).join('')}</aside>`}
function header(path){return `<header class="site-header"><a class="brand" href="#/" aria-label="萤火手记首页"><span class="brand-mark">f</span><span><strong>萤火手记</strong><small>FIREFLY / FIELD NOTES</small></span></a><nav id="main-nav" class="nav" aria-label="网站导航">${[['/','首页'],['/articles','文章'],['/articles?topic=web','主题'],['/projects','项目']].map(([p,n])=>`<a href="#${p}" ${((p===path&&!location.hash.includes('topic='))||(n==='主题'&&location.hash.includes('topic=')))?'aria-current="page"':''}>${n}</a>`).join('')}<a href="#/" data-about>关于</a></nav><div class="header-tools"><button class="search-button" data-search aria-label="搜索文章">${icon('search')}<kbd>Ctrl K</kbd></button><button class="menu-button" data-menu aria-expanded="false" aria-controls="main-nav" aria-label="展开导航">${icon('menu')}</button></div></header>`}
const footer=()=>`<footer class="footer"><div>© 2026 萤火手记 · firefly1v<br><small>记录学习、思考与生活。</small></div><div><a href="#/articles?kind=日记">日记</a><a href="#/" data-extra="resources">资源</a><a href="#/" data-extra="archive">归档</a><a href="https://github.com/InInNHD" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div></footer>`
function home(params){
  const a=articles[0],legacy=params.layout==='v2'
  return `<div class="${legacy?'legacy':''}">${legacy?'<p class="legacy-label">结构对照：同样的8篇演示文章与同一配色，模拟第二版“大首屏＋文章流＋侧栏”。不是第二版真实运行页面。</p>':''}<section class="intro"><div><span class="eyebrow">你好，我是 firefly1v</span><h1>把问题弄明白，<br><em>把思考留下来。</em></h1><p class="lead">从一个可运行的小例子出发，记录 Java 开发、前端实践和项目中的思考。这里是我的笔记，也是持续生长的学习地图。</p><div class="intro-links">${link('/articles','翻开笔记 '+icon(),{},'button primary')}${link('/projects','看看做过的项目 ↗',{},'text-link')}</div></div>${legacy?'<div class="legacy-hero">'+art('paper')+'</div>':`<aside class="current-note"><span class="eyebrow"><i class="status-dot"></i>当前项目</span><h2>一个慢慢长大的网站</h2><p>Vue · Java · MySQL<br>从内容记录，到完整的个人空间。</p><a href="#/projects">PersonalWebsite2 ${icon()}</a></aside>`}</section><section><div class="section-head"><div><span class="eyebrow">${legacy?'LATEST NOTES':'START HERE'}</span><h2>${legacy?'最近的记录':'先从这篇开始'}</h2></div>${link('/articles','全部文章 '+icon(),{},'text-link')}</div><div class="home-feature"><article class="feature-card"><a class="feature-art" href="${e(articleUrl(a,'/'))}" aria-label="阅读：${e(a.title)}">${art(a.art)}</a><div class="feature-copy"><div><span class="chip">${legacy?'置顶':'精选笔记'}</span></div><h3><a href="${e(articleUrl(a,'/'))}">${e(a.title)}</a></h3><p>${e(a.summary)}</p>${meta(a)}</div></article>${pathCard()}</div></section><div class="home-bottom"><section><div class="section-head"><h2>最近留下的记录</h2><span class="muted"><small>演示日期 / 2026.10</small></span></div>${(legacy?articles.slice(1):articles.slice(1,5)).map(a=>`<article class="entry-row"><time>${a.date.slice(5).replace('-',' / ')}</time><div><h3><a href="${e(articleUrl(a,'/'))}">${e(a.title)}</a></h3><p>${e(a.summary)}</p></div><a href="${e(articleUrl(a,'/'))}" aria-label="阅读：${e(a.title)}">↗</a></article>`).join('')}</section><aside><div class="section-head"><h2>${legacy?'作者与导航':'代码里的实践'}</h2></div>${legacy?'<p class="muted">firefly1v · 记录学习、思考与生活。</p>':''}${[['PersonalWebsite2','把笔记、写作和展示连在一起','Vue / Java'],['starticket','围绕票务流程阅读状态与约束','Java'],['dsh-recheck','让结论能回到对应的证据','JavaScript']].map(([name,desc,tech])=>`<a class="mini-project" href="#/projects"><strong>${name} ↗</strong><p>${desc}</p><small>${tech}</small></a>`).join('')}</aside></div></div>`
}
function articleCard(a,q,from){return `<article class="article-card"><a class="card-art" href="${e(articleUrl(a,from))}" aria-label="阅读：${e(a.title)}">${art(a.art)}</a><div class="card-copy"><span class="eyebrow">${e(a.tag)} / ${e(a.kind)}</span><h2><a href="${e(articleUrl(a,from))}">${highlight(a.title,q)}</a></h2><p>${highlight(q&&a.body.toLocaleLowerCase().includes(q.toLocaleLowerCase())?a.body:a.summary,q)}</p><div class="meta"><time>${a.date.replaceAll('-','.')} · 演示</time><span>${a.minutes} 分钟</span>${!a.art?'<span>默认封面</span>':''}</div></div></article>`}
function library(params){const items=filterArticles(params),paged=pageItems(items,params.page),from='/articles'+(Object.keys(params).length?'?'+new URLSearchParams(params):''),topic=topics.find(t=>t.id===params.topic)
  return `<section class="page-heading"><span class="eyebrow">THE NOTEBOOK</span><h1>${topic?e(topic.name):params.q?'查找一段记录':'文章与笔记'}</h1><p>${topic?e(topic.description):'把遇到的问题拆开，再把理解连起来。沿着一个主题，或从一个关键词开始。'}</p></section><div class="library-layout"><aside class="library-side" aria-label="文章栏目"><h2>按栏目浏览</h2>${['','笔记','心得','日记'].map(kind=>link('/articles',kind||'全部记录',{...params,kind,page:1},(params.kind||'')===kind?'selected':'')).join('')}<div class="topic-nav"><h2>学习专题 · 演示</h2>${topics.map(t=>link('/articles',t.name,{topic:t.id},params.topic===t.id?'selected':'')).join('')}${params.topic?link('/articles','退出专题',{},'text-link'):''}</div></aside><section aria-label="文章结果"><form id="library-search" class="search-line"><input name="q" aria-label="搜索演示文章" type="search" maxlength="100" value="${e(params.q||'')}" placeholder="搜索标题、摘要与正文…"><button type="submit" aria-label="提交搜索">${icon('search')}</button></form><div class="filter-row"><label>标签 <select id="tag-filter"><option value="">全部标签</option>${[...new Set(articles.map(a=>a.tag))].map(tag=>`<option ${tag===params.tag?'selected':''}>${e(tag)}</option>`).join('')}</select></label><button data-reset class="text-link">重置条件</button><div class="view-tools" role="group" aria-label="列表密度"><button data-view="cards" aria-pressed="${params.view!=='compact'}">卡片</button><button data-view="compact" aria-pressed="${params.view==='compact'}">紧凑</button></div></div><div class="results-head"><span role="status">${params.q?'“'+e(params.q)+'” · ':''}找到 ${items.length} 篇演示文章</span><span>${params.q?'标题命中优先':'按演示日期排列'}</span></div><div class="article-grid ${params.view==='compact'?'compact':''}">${paged.items.length?paged.items.map(a=>articleCard(a,params.q,from)).join(''):'<div class="empty"><span class="eyebrow">NO MATCHES</span><h2>暂时没找到这段记录</h2><p>试试更短的关键词，或清空栏目与标签。</p><button data-reset>查看全部文章</button></div>'}</div>${items.length?`<nav class="pagination" aria-label="文章分页"><button data-page="${paged.page-1}" ${paged.page===1?'disabled':''}>← 上一页</button><span>${paged.page} / ${paged.pages}</span><button data-page="${paged.page+1}" ${paged.page===paged.pages?'disabled':''}>下一页 →</button></nav>`:''}</section></div>`}
const eventNames={PUSH:'推送',RELEASE:'Release',COMMIT:'历史提交'}
function projects(params){
  if(projectError)return '<section class="empty"><h1>项目快照暂时无法读取</h1><p>演示文章仍可使用。项目资料来自本站公开快照。</p><button data-retry>重新读取</button></section>'
  if(!snapshot)return '<section class="empty" role="status">正在读取公开项目快照…</section>'
  const projects=snapshot.projects, selected=projects.find(p=>p.name==='PersonalWebsite2'),events=snapshot.events.filter(x=>(!params.repo||x.repo===params.repo)&&(!params.kind||x.kind===params.kind)),paged=pageItems(events,params.page,6)
  return `<section class="page-heading"><span class="eyebrow">BUILT & LEARNED</span><h1>在项目里，把想法落地。</h1><p>公开仓库记录实现，笔记记录理解。这里保留完整项目，也给值得展开的实践多一点空间。</p></section><section class="project-feature"><div class="terminal-art"><div class="terminal"><div class="terminal-top">● ● ●　 PersonalWebsite2</div><div class="terminal-body"><span>$ open field-notes</span><br><strong>一处自己的记录空间。</strong><div class="terminal-path">Vue　 →　 Spring Boot<br>　　　　　　↓<br>　　　　　MySQL<br><br>写下问题 → 整理内容 → 公开分享</div></div></div></div><div class="project-feature-copy"><span class="chip">精选项目 / 案例提案</span><h2>PersonalWebsite2</h2><p>用 Vue、Java 与 MySQL 搭建个人网站，把笔记、写作后台、图片和备份恢复放进一条完整流程。</p><div class="meta"><span>Vue 3</span><span>Java 17</span><span>MySQL</span></div><div class="project-actions"><button class="primary" data-case="PersonalWebsite2">展开项目说明 ↗</button>${selected?repoLink(selected,'查看源码 ↗'):''}</div></div></section><div class="section-head"><h2>全部公开仓库 <span class="muted">/ ${projects.length}</span></h2><span class="eyebrow">PUBLIC REPOSITORIES</span></div><p class="source-note">快照：${e(snapshot.syncedAt.slice(0,10))} · 仓库信息不等于本人贡献证明；Fork 单独标注。更新链来自该快照，非实时同步。</p><div class="project-grid">${projects.map(p=>`<article class="project-card"><span class="eyebrow">${p.fork?'FORK / 上游项目副本':'PUBLIC REPOSITORY'}</span><h3>${e(p.name)}</h3><p>${e(p.description||'暂无仓库简介，个人贡献说明待补充。')}</p><div class="meta"><span>${e(p.language||'语言未标注')}</span>${p.archived?'<span>已归档</span>':''}</div><div class="project-actions">${repoLink(p)}<button data-case="${e(p.name)}">项目说明</button></div></article>`).join('')}</div><section class="events"><div class="section-head"><h2>项目更新链</h2><small class="muted">区分事件来源，保留发生日期</small></div><div class="filter-row"><label>项目 <select id="repo-filter"><option value="">全部项目</option>${projects.map(p=>`<option value="${e(p.fullName)}" ${params.repo===p.fullName?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><label>类型 <select id="event-filter"><option value="">全部记录</option>${Object.entries(eventNames).map(([id,name])=>`<option value="${id}" ${params.kind===id?'selected':''}>${name}</option>`).join('')}</select></label><span class="muted"><small>${events.length} 条</small></span></div>${paged.items.length?paged.items.map(v=>`<div class="event"><time>${new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date(v.date))}</time><span class="chip">${eventNames[v.kind]}</span><a href="${external(v.url)}" target="_blank" rel="noopener noreferrer">${e(v.title)}<br><small class="muted">${e(v.repo)} ↗</small></a></div>`).join(''):'<p class="empty">当前快照中没有符合条件的记录。</p>'}${events.length?`<nav class="pagination" aria-label="更新链分页"><button data-page="${paged.page-1}" ${paged.page===1?'disabled':''}>← 上一页</button><span>${paged.page} / ${paged.pages}</span><button data-page="${paged.page+1}" ${paged.page===paged.pages?'disabled':''}>下一页 →</button></nav>`:''}<p class="source-note">推送不等同于提交时间；历史提交不能还原所有推送。Fork 历史提交沿用“只收录本人提交”的范围。</p></section>`
}
function reading(id,params){const a=articles.find(x=>x.id===id);if(!a)return '<section class="empty"><h1>没有这篇演示文章</h1><p>试试从文章库重新打开。</p><a class="button" href="#/articles">返回文章库</a></section>'
  const from=params.from?.startsWith('/articles')||params.from==='/'?params.from:'/articles'
  const sampleCode=a.id==='request'?`// 仅演示数据路径，不是完整的生产接口\n@GetMapping("/articles/{id}")\npublic Article find(@PathVariable long id) {\n    return articleService.findPublished(id);\n}`:a.id==='restore'?`# 先恢复到独立环境，再核对数据与文件\ncompare_schema(source, restored)\ncompare_rows(source, restored)\ncompare_media_hashes(source, restored)`:`// 把前置条件与预期结果写清楚\nif (!canProceed(currentState)) {\n    return Result.rejected("请先检查当前状态");\n}\nreturn executeOnce(request);`
  const related=topics.find(t=>t.ids.includes(a.id)),next=related?.ids[related.ids.indexOf(a.id)+1],nextArticle=articles.find(x=>x.id===next)
  return `<div class="reading-progress" aria-hidden="true"></div><nav class="breadcrumb" aria-label="面包屑"><a href="#${e(from)}">← 返回${from==='/'?'首页':'文章列表'}</a><span>/</span><span>${e(a.kind)}</span><span>/</span><span>${e(a.tag)}</span></nav><header class="reader-heading"><span class="chip">${related?e(related.name):'日常记录'} · 演示正文</span><h1>${e(a.title)}</h1><div class="meta"><span>firefly1v</span><span>·</span><time>${a.date}（演示日期）</time><span>约 ${a.minutes} 分钟（示意）</span></div><p class="summary">${e(a.summary)}</p></header><div class="reader-layout"><article class="prose" id="reading-body"><div class="callout">本页为专门编写的界面演示，未使用数据库中的私人草稿。代码用于说明，不可直接当作完整实现。</div><h2 id="section-1">01　${e(a.section)}</h2><p>${e(a.body)}</p><p>理解一个问题，可以先回答三个小问题：从哪里开始、经过什么处理、最后观察到了什么。先把路径说清楚，细节才有合适的位置。</p><figure class="diagram">${art(a.art)}<figcaption>图 1 · 原创示意图，用于检验正文图像与说明的阅读节奏。</figcaption></figure><h2 id="section-2">02　把复杂过程拆成小步骤</h2><p>每一步只负责一个明确的变化。阅读代码时，把输入、输出和限制写在一起，比记住一长串调用更容易回顾。</p><ul><li>输入：这一步接收什么，哪些值需要先检查。</li><li>处理：是否改变状态，失败时会留下什么。</li><li>输出：调用方凭什么判断已经成功。</li></ul><div class="code-block"><div class="code-bar"><span>${a.id==='restore'?'PYTHON / 示意':'JAVA / 示意'}</span><button data-copy-code>复制代码</button></div><pre><code>${e(sampleCode)}</code></pre></div><h2 id="section-3">03　让结论可以被验证</h2><p>正常结果只是其中一部分。还可以检查空输入、重复操作、网络中断，以及操作只完成了一半的情况。失败路径的设计，决定了下一次尝试是否容易。</p><div class="callout"><strong>留一个可重复的小检查。</strong><br>明确条件与预期，记录实际结果。尚未验证的部分保留说明，方便以后继续。</div><p>这也适用于笔记：不要只保存答案，还要保存得出答案的路径。再次遇到同类问题时，就能知道哪些条件仍然成立。</p><h2 id="section-4">04　把这条线继续连下去</h2><p>用几句话记录本次的边界与下一步，再链接到同主题的文章。孤立的笔记由此变成可顺着阅读的知识路径。</p><p class="muted">演示正文结束。正式文章的事实、代码和个人经历需要作者审阅后另行发布。</p><div class="reading-end"><a href="#${e(from)}">← 回到刚才的列表</a>${nextArticle?`<a href="${e(articleUrl(nextArticle,from))}">专题下一篇：${e(nextArticle.title)} →</a>`:link('/articles','继续浏览笔记 →')}</div></article><aside class="reading-side"><div class="reader-controls" role="group" aria-label="阅读设置"><button data-font="16" aria-label="常规字号" aria-pressed="${fontSize===16}">A</button><button data-font="19" aria-label="大字号" aria-pressed="${fontSize===19}">A＋</button><button data-focus aria-pressed="${focused}">${focused?'退出专注':'专注阅读'}</button><button data-share>复制链接</button></div><details class="toc" ${window.innerWidth>760?'open':''}><summary>本篇目录</summary>${[a.section,'把复杂过程拆成小步骤','让结论可以被验证','把这条线继续连下去'].map((title,i)=>`<a href="#section-${i+1}" data-section="section-${i+1}">${String(i+1).padStart(2,'0')}　${e(title)}</a>`).join('')}</details>${pathCard()}</aside></div>`
}
function render({preserve=false}={}){
  const {path,params}=route(),y=window.scrollY;observer?.disconnect()
  document.body.classList.toggle('focus-mode',focused&&path.startsWith('/article/'))
  document.documentElement.style.setProperty('--reading-size',fontSize+'px')
  let content,title
  if(path==='/'){content=home(params);title='首页'}else if(path==='/articles'){content=library(params);title='文章库'}else if(path==='/projects'){content=projects(params);title='项目'}else if(path.startsWith('/article/')){content=reading(path.split('/')[2],params);title=articles.find(a=>a.id===path.split('/')[2])?.title||'文章不存在'}else{title='页面不存在';content='<section class="empty"><h1>这个样稿页面不存在</h1><p>可以从首页继续浏览。</p><a class="button" href="#/">返回首页</a></section>'}
  app.innerHTML=`<div class="wrap">${header(path)}<main id="main" tabindex="-1">${content}</main>${footer()}</div>`
  document.title=`${title} · 萤火手记 V3 样稿`
  $('#compare').textContent=params.layout==='v2'?'返回第三版样稿':'对照第二版结构'
  if(path.startsWith('/article/')){observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){document.querySelectorAll('[data-section]').forEach(a=>{a.classList.toggle('active',a.dataset.section===entry.target.id);if(a.dataset.section===entry.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}},{rootMargin:'-5% 0px -65% 0px'});document.querySelectorAll('.prose h2').forEach(h=>observer.observe(h))}
  requestAnimationFrame(()=>{window.scrollTo(0,preserve?y:(positions.get(location.hash||'#/')||0));updateProgress()})
}
function updateParams(changes){const r=route();const next=href(r.path,{...r.params,...changes});if(r.path==='/projects')positions.set(next,window.scrollY);location.hash=next.slice(1)}
function notify(message){clearTimeout(noticeTimer);$('#notice').textContent=message;noticeTimer=setTimeout(()=>{$('#notice').textContent=''},3500)}
function openInfo(title,html){returnFocus=document.activeElement;$('#info-title').textContent=title;$('#info-body').innerHTML=html;infoDialog.showModal()}
async function copy(text){try{await navigator.clipboard.writeText(text);notify('已复制')}catch{openInfo('请手动复制',`<p>当前浏览器不允许自动复制。请选中以下内容：</p><textarea readonly rows="6" aria-label="待复制内容" style="width:100%">${e(text)}</textarea>`);$('#info-body textarea').select()}}
document.addEventListener('click',event=>{
  const target=event.target.closest('button,a');if(!target)return
  const d=target.dataset
  // 跳转正文只移动焦点，避免#main被样稿的hash路由当成新页面。
  if(target.classList.contains('skip')){event.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}
  if(target.matches('a[href^="#/"]')&&!('about'in d)&&!('extra'in d)){positions.set(location.hash||'#/',window.scrollY);const nav=$('#main-nav');nav?.classList.remove('open');const menu=$('[data-menu]');menu?.setAttribute('aria-expanded','false')}
  if('search'in d){returnFocus=target;searchDialog.showModal();$('#global-query').focus()}
  if('close'in d)target.closest('dialog').close()
  if('menu'in d){const nav=$('#main-nav'),open=nav.classList.toggle('open');target.setAttribute('aria-expanded',String(open));target.setAttribute('aria-label',open?'收起导航':'展开导航')}
  if('reset'in d)location.hash='/articles'
  if('page'in d)updateParams({page:d.page})
  if('view'in d)updateParams({view:d.view})
  if('section'in d){event.preventDefault();const heading=$('#'+d.section);heading.scrollIntoView({behavior:'auto',block:'start'});heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true})}
  if('font'in d){fontSize=Number(d.font);document.documentElement.style.setProperty('--reading-size',fontSize+'px');document.querySelectorAll('[data-font]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.font)===fontSize)))}
  if('focus'in d){focused=!focused;render({preserve:true});requestAnimationFrame(()=>$('[data-focus]')?.focus({preventScroll:true}))}
  if('copyCode'in d)copy($('.code-block code').textContent)
  if('share'in d)copy(location.origin+location.pathname+'#'+route().path)
  if('case'in d){const p=snapshot?.projects.find(p=>p.name===d.case);if(p)openInfo(p.name,`<span class="chip">${p.fork?'Fork · 不代表上游贡献归本人':'案例内容提案 · 待作者审阅'}</span><h3>项目做什么</h3><p>${e(p.description||'仓库尚未提供简介。')}</p><h3>目前可以核对的内容</h3><p>${p.name==='PersonalWebsite2'?'当前工作区已有文章阅读、后台写作、媒体和备份恢复流程；第二版候选代码已提交。':p.fork?'这是公开的上游项目副本。具体修改范围需逐条核对本人提交，当前不补写贡献。':'以上介绍来自公开仓库快照。本样稿未独立验收该项目功能，也未确认本人独立完成的范围。'}</p><h3>正式案例还需补充</h3><p>本人负责部分、一个具体难点、取舍依据和可核对的结果。性能数字与项目截图需有证据后填写。</p><div class="project-actions">${repoLink(p,'打开公开仓库 ↗')}${link('/articles','阅读演示笔记 →')}</div>`)}
  if('about'in d){event.preventDefault();openInfo('你好，我是 firefly1v。','<p>从一个可运行的小例子出发，记录Java开发、前端实践和项目中的思考。</p><p>笔记用于整理知识，心得用于回看选择，公开日记则留给愿意分享的日常。</p><p>本轮评审首页、文章库、项目与阅读四类页面。完整关于页继续沿用第二版能力。</p><a class="button" href="https://github.com/InInNHD" target="_blank" rel="noopener noreferrer">GitHub / InInNHD ↗</a>')}
  if('extra'in d){event.preventDefault();openInfo(d.extra==='archive'?'归档入口':'资源入口','<p>这里保留现有页面的导航位置。本轮未重新制作该页面，正式实现时接入第二版现有功能。</p>'+link('/articles','先浏览演示文章 →',{},'button'))}
  if('retry'in d)loadSnapshot()
  if(target.closest('#info-dialog')&&target.matches('a[href^="#/"]'))infoDialog.close()
})
document.addEventListener('submit',event=>{if(!['global-search','library-search'].includes(event.target.id))return;event.preventDefault();const q=new FormData(event.target).get('q').trim();if(event.target.id==='global-search'){searchDialog.close();location.hash=href('/articles',{q}).slice(1)}else updateParams({q,page:1})})
document.addEventListener('change',event=>{const t=event.target;if(t.id==='tag-filter')updateParams({tag:t.value,page:1});if(t.id==='repo-filter')updateParams({repo:t.value,page:1});if(t.id==='event-filter')updateParams({kind:t.value,page:1})})
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!searchDialog.open&&!infoDialog.open){returnFocus=document.activeElement;searchDialog.showModal();$('#global-query').focus()}}if(event.key==='Escape'&&!searchDialog.open&&!infoDialog.open){$('#main-nav')?.classList.remove('open');const b=$('[data-menu]');if(b?.getAttribute('aria-expanded')==='true'){b.setAttribute('aria-expanded','false');b.setAttribute('aria-label','展开导航');b.focus()}}})
for(const dialog of [searchDialog,infoDialog])dialog.addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true})})
$('#compare').addEventListener('click',()=>{const {params}=route();location.hash=href('/',params.layout==='v2'?{}:{layout:'v2'}).slice(1)})
window.addEventListener('hashchange',()=>{positions.set(previousKey,window.scrollY);previousKey=location.hash||'#/';searchDialog.close();infoDialog.close();render();$('#main').focus({preventScroll:true})})
function updateProgress(){const body=$('#reading-body'),bar=$('.reading-progress');if(!body||!bar)return;const start=body.getBoundingClientRect().top+window.scrollY;const distance=Math.max(1,body.offsetHeight-window.innerHeight);bar.style.width=Math.min(100,Math.max(0,(window.scrollY-start)/distance*100))+'%'}
window.addEventListener('scroll',updateProgress,{passive:true})
async function loadSnapshot(){projectError=false;try{const response=await fetch('projects.json');if(!response.ok)throw new Error('snapshot');const data=await response.json();if(!Array.isArray(data.projects)||!Array.isArray(data.events))throw new Error('format');snapshot=data}catch{projectError=true}if(route().path==='/projects')render({preserve:true})}
render();loadSnapshot()
